-- Rattachement facultatif des participations à une cagnotte
alter table public.contributions
add column if not exists fundraiser_id bigint references public.fundraisers(id) on delete set null;

drop policy if exists "Public can view contributions" on public.contributions;
create policy "Public can view contributions"
on public.contributions
for select
to anon
using (true);

drop policy if exists "Public can create contributions" on public.contributions;
create policy "Public can create contributions"
on public.contributions
for insert
to anon
with check (
  char_length(trim(name)) between 1 and 50
  and amount >= 1
  and amount <= 5000
  and (
    fundraiser_id is null
    or exists (
      select 1 from public.fundraisers f
      where f.id = fundraiser_id
        and f.status = 'approved'
    )
  )
);

grant select, insert on table public.contributions to anon;

