  if p_status not in ('approved','rejected') then
    raise exception 'invalid status';
  end if;

  update public.fundraisers
  set status = p_status
  where id = p_id
    and status = 'pending';

  return found;
end;
$fundstatus$;

grant execute on function public.admin_set_fundraiser_status(bigint, text) to anon;

-- =====================================================
-- ============================================================
-- ADMIN : liste consolidée des accès + profils
-- Utilise des noms de sortie distincts pour éviter toute ambiguïté
-- avec les colonnes de tables.
-- ============================================================
create or replace function public.admin_list_people_access()
returns table(
  access_id bigint,
  person_name text,
  access_code text,
  active_access boolean,
  is_admin_access boolean,
  access_created_at timestamptz,
  last_used_at timestamptz,
  profile_id bigint,
  relation text,
  avatar text,
  bio text,
  profile_created_at timestamptz,
  profile_updated_at timestamptz
)
language plpgsql
security definer
set search_path = public
as $peopleaccess$
begin
  perform public.assert_admin_header();

  return query
  select
    lac.id as access_id,
    lac.label as person_name,
    lac.code as access_code,
    lac.active as active_access,
    lac.is_admin as is_admin_access,
    lac.created_at as access_created_at,
    lac.last_used_at,
    gp.id as profile_id,
    gp.relation,
    gp.avatar,
    gp.bio,
    gp.created_at as profile_created_at,
    gp.updated_at as profile_updated_at
  from public.list_access_codes as lac
  left join public.guest_profiles as gp
    on lower(trim(gp.name)) = lower(trim(lac.label))
  order by lac.created_at desc;
end;
$peopleaccess$;

grant execute on function public.admin_list_people_access() to anon;

drop function if exists public.admin_list_access_usage();
create or replace function public.admin_list_access_usage()
returns table(
  access_id bigint,
  person_name text,
  access_code text,
  active_access boolean,
  is_admin_access boolean,
  hydra_player_name text,
  authorization_count bigint,
  last_authorized_at timestamptz,
  duplicate_count_for_name bigint
)
language plpgsql
security definer
set search_path = public
as $accessusage$
begin
  perform public.assert_admin_header();

  return query
  select
    lac.id as access_id,
    lac.label as person_name,
    lac.code as access_code,
    lac.active as active_access,
    lac.is_admin as is_admin_access,
    lac.hydra_player_name,
    count(la.id)::bigint as authorization_count,
    max(la.authorized_at) as last_authorized_at,
    (
      select count(*)
      from public.list_access_codes dup
      where lower(trim(dup.label)) = lower(trim(lac.label))
    )::bigint as duplicate_count_for_name
  from public.list_access_codes as lac
  left join public.list_access_authorizations as la
    on la.access_id = lac.id
  group by lac.id,lac.label,lac.code,lac.active,lac.is_admin,lac.hydra_player_name
  order by lac.created_at desc;
end;
$accessusage$;

grant execute on function public.admin_list_access_usage() to anon;

create or replace function public.admin_list_access_stats()
returns table(
  active_accesses bigint,
  total_access_codes bigint,
  total_authorizations bigint,
  used_accesses bigint,
  duplicate_people bigint
)
language plpgsql
security definer
set search_path = public
as $accessstats$
begin
  perform public.assert_admin_header();

  return query
  select
    (select count(*) from public.list_access_codes where active=true)::bigint,
    (select count(*) from public.list_access_codes)::bigint,
    (select count(*) from public.list_access_authorizations)::bigint,
    (select count(distinct access_id) from public.list_access_authorizations)::bigint,
    (
      select count(*)
      from (
        select lower(trim(label)) as normalized_label
        from public.list_access_codes
        group by lower(trim(label))
        having count(*) > 1
      ) d
    )::bigint;
end;
$accessstats$;

grant execute on function public.admin_list_access_stats() to anon;

create or replace function public.admin_list_access_duplicates()
returns table(
  person_name text,
  access_count bigint,
  access_codes text
)
language plpgsql
security definer
set search_path = public
as $accessdups$
begin
  perform public.assert_admin_header();

  return query
  select
    min(lac.label) as person_name,
    count(*)::bigint as access_count,
    string_agg(lac.code, ', ' order by lac.created_at desc) as access_codes
  from public.list_access_codes as lac
  group by lower(trim(lac.label))
  having count(*) > 1
  order by count(*) desc, min(lac.label);
end;
$accessdups$;

grant execute on function public.admin_list_access_duplicates() to anon;



