create or replace function public.admin_delete_community_post(
  p_id bigint
  )
returns boolean
language plpgsql
security definer
set search_path = public, storage
as $admincommunitydel$
declare
  files jsonb;
  file_item jsonb;
  file_path text;
begin
  perform public.assert_admin_header();

  select attachments
  into files
  from public.community_posts
  where id = p_id;

  if files is null then
    return false;
  end if;

  for file_item in
    select value
    from jsonb_array_elements(coalesce(files, '[]'::jsonb))
  loop
    file_path := regexp_replace(
      file_item->>'url',
      '^.*/storage/v1/object/public/community-files/',
      ''
    );

    if file_path is not null and file_path <> '' then
      delete from storage.objects
      where bucket_id = 'community-files'
        and name = file_path;
    end if;
  end loop;

  delete from public.community_posts where id = p_id;
  return found;
end;
$admincommunitydel$;

grant execute on function public.admin_delete_community_post(bigint) to anon;


