    e.session_id,
    e.event_type,
    e.page_path,
    e.event_label,
    e.metadata,
    e.created_at
  from public.extension_telemetry_events e
  order by e.created_at desc
  limit greatest(1, least(coalesce(p_limit, 250), 500));
end;
$admintelemetry$;

grant execute on function public.admin_list_extension_events(integer) to anon;

create or replace function public.admin_extension_telemetry_stats()
returns table(
  total_events bigint,
  installations bigint,
  sessions bigint,
  active_installations_24h bigint,
  events_24h bigint,
  page_views_24h bigint
)
language plpgsql
security definer
set search_path = public
as $admintelemetrystats$
begin
  perform public.assert_admin_header();

  return query
  select
    count(*)::bigint,
    count(distinct installation_id)::bigint,
    count(distinct session_id)::bigint,
    count(distinct installation_id) filter (where created_at >= now() - interval '24 hours')::bigint,
    count(*) filter (where created_at >= now() - interval '24 hours')::bigint,
    count(*) filter (
      where event_type = 'page_view'
        and created_at >= now() - interval '24 hours'
    )::bigint
  from public.extension_telemetry_events;
end;
$admintelemetrystats$;

grant execute on function public.admin_extension_telemetry_stats() to anon;


create or replace function public.authorize_list_access(p_code text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $auth$
declare
  v_id bigint;
  v_label text;
  v_is_admin boolean;
  v_ip text;
  v_attempts integer := 0;
  v_blocked_until timestamptz;
  v_retry integer := 0;
begin
  -- Supabase expose l'IP cliente via les en-têtes de requête.
  v_ip := left(coalesce(
    current_setting('request.headers', true)::json->>'cf-connecting-ip',
    split_part(current_setting('request.headers', true)::json->>'x-forwarded-for', ',', 1),
    current_setting('request.headers', true)::json->>'x-real-ip',
    'unknown'
  ), 120);
  v_ip := nullif(trim(v_ip), '');
  if v_ip is null then v_ip := 'unknown'; end if;

  select failed_attempts, blocked_until
    into v_attempts, v_blocked_until
  from public.list_access_rate_limits
  where client_ip = v_ip;

  if v_blocked_until is not null and v_blocked_until > now() then
    v_retry := greatest(1, ceil(extract(epoch from (v_blocked_until-now())))::integer);
    return jsonb_build_object(
      'authorized', false,
      'rate_limited', true,
      'retry_after_seconds', v_retry
    );
  end if;

  select lac.id, lac.label, lac.is_admin
    into v_id, v_label, v_is_admin
  from public.list_access_codes as lac
  where lac.active = true
    and lac.code = trim(coalesce(p_code, ''))
  limit 1;

  if v_id is null then
    v_attempts := coalesce(v_attempts,0) + 1;
    v_retry := case
      when v_attempts >= 20 then 300
      when v_attempts >= 12 then 60
      when v_attempts >= 8 then 15
      when v_attempts >= 5 then 5
      else 0
    end;

    insert into public.list_access_rate_limits(client_ip,failed_attempts,last_failed_at,blocked_until)
    values(
      v_ip,
      v_attempts,
      now(),
      case when v_retry > 0 then now() + make_interval(secs => v_retry) else null end
    )
    on conflict (client_ip) do update
      set failed_attempts=excluded.failed_attempts,
          last_failed_at=excluded.last_failed_at,
          blocked_until=excluded.blocked_until;

    return jsonb_build_object(
      'authorized', false,
      'rate_limited', v_retry > 0,
      'retry_after_seconds', v_retry
    );
  end if;

  -- Une authentification correcte remet le compteur à zéro.
  delete from public.list_access_rate_limits where client_ip = v_ip;

  update public.list_access_codes as lac
  set last_used_at = now()
  where lac.id = v_id;

  insert into public.list_access_authorizations(access_id, authorized_at)
  values(v_id, now());

  return jsonb_build_object(
    'authorized', true,
    'access_id', v_id,
    'label', v_label,
    'is_admin', v_is_admin
  );
end;
$auth$;

grant execute on function public.authorize_list_access(text) to anon;

drop function if exists public.get_private_gifts(text);

create or replace function public.get_private_gifts(p_code text)
returns table (
  id text,sort_order integer,cat text,title text,price text,description text,image text,
  official_label text,official_url text,target_amount numeric,allow_contributions boolean,
  allow_reservation boolean,funding_note text,contributed_amount numeric,remaining_amount numeric,
  contribution_count bigint,participant_count bigint,my_contribution_count bigint,my_contributed_amount numeric,reserved_by text
)
language plpgsql security definer set search_path=public
as $$
begin
  if not exists(select 1 from public.list_access_codes where active=true and code=trim(coalesce(p_code,''))) then return; end if;
  return query
  select g.id,g.sort_order,g.cat,g.title,g.price,g.description,g.image,g.official_label,g.official_url,
    g.target_amount,g.allow_contributions,g.allow_reservation,g.funding_note,
    coalesce((select sum(c.amount) from public.gift_contributions c where c.gift_id=g.id),0)::numeric,
    greatest(g.target_amount-coalesce((select sum(c.amount) from public.gift_contributions c where c.gift_id=g.id),0),0)::numeric,
    (select count(*) from public.gift_contributions c where c.gift_id=g.id),
    (select count(distinct lower(trim(c.name))) from public.gift_contributions c where c.gift_id=g.id),
    (select count(*) from public.gift_contributions c where c.gift_id=g.id and lower(trim(c.name)) = lower(trim((select lac.label from public.list_access_codes lac where lac.active=true and lac.code=trim(coalesce(p_code,'')) limit 1)))),
    (select coalesce(sum(c.amount),0)::numeric from public.gift_contributions c where c.gift_id=g.id and lower(trim(c.name)) = lower(trim((select lac.label from public.list_access_codes lac where lac.active=true and lac.code=trim(coalesce(p_code,'')) limit 1)))),
    (select r.name from public.reservations r where r.gift_id=g.id limit 1)
  from public.gift_catalog g
  where coalesce(g.archived,false) = false
  order by g.sort_order,g.id;
end;
$$;

grant execute on function public.get_private_gifts(text) to anon;

create or replace function public.add_private_gift_contribution(
  p_code text,p_gift_id text,p_name text,p_amount numeric,p_message text default null
)
returns bigint
language plpgsql
security definer
set search_path=public
as $$
declare v_target numeric;v_current numeric;v_remaining numeric;v_allow boolean;v_id bigint;v_name text;
begin
  select label into v_name from public.list_access_codes
  where active=true and code=trim(coalesce(p_code,'')) limit 1;
  if v_name is null then raise exception 'Accès refusé.' using errcode='42501'; end if;
  select target_amount,allow_contributions into v_target,v_allow from public.gift_catalog where id=p_gift_id for update;
  if v_target is null then raise exception 'Cadeau introuvable.'; end if;
  if not v_allow then raise exception 'Les participations ne sont pas activées pour ce cadeau.'; end if;
  if p_amount is null or p_amount<=0 or p_amount>50000 then raise exception 'Montant invalide.'; end if;
  if exists(select 1 from public.reservations where gift_id=p_gift_id) then raise exception 'Ce cadeau est déjà réservé en totalité.'; end if;
  select coalesce(sum(amount),0) into v_current from public.gift_contributions where gift_id=p_gift_id;
  v_remaining:=greatest(v_target-v_current,0);
  if v_remaining<=0 then raise exception 'Ce cadeau est déjà entièrement financé.'; end if;
  if p_amount>v_remaining then raise exception 'Le maximum est % €.',to_char(v_remaining,'FM999999990.00'); end if;
  insert into public.gift_contributions(gift_id,name,amount,message)
  values(p_gift_id,v_name,round(p_amount,2),nullif(trim(p_message),''))
  returning id into v_id;
  return v_id;
end;
$$;

drop function if exists public.admin_list_gift_catalog();

create or replace function public.admin_list_gift_catalog()
returns table (
  id text,sort_order integer,cat text,title text,price text,description text,image text,
  official_label text,official_url text,target_amount numeric,allow_contributions boolean,
  allow_reservation boolean,funding_note text,contributed_amount numeric,remaining_amount numeric,
  contribution_count bigint,participant_count bigint,reserved_by text
)
language plpgsql security definer set search_path=public
as $$
begin
  perform public.assert_admin_header();
  return query
  select g.id,g.sort_order,g.cat,g.title,g.price,g.description,g.image,g.official_label,g.official_url,
    g.target_amount,g.allow_contributions,g.allow_reservation,g.funding_note,
    coalesce((select sum(c.amount) from public.gift_contributions c where c.gift_id=g.id),0)::numeric,
    greatest(g.target_amount-coalesce((select sum(c.amount) from public.gift_contributions c where c.gift_id=g.id),0),0)::numeric,
    (select count(*) from public.gift_contributions c where c.gift_id=g.id),
    (select count(distinct lower(trim(c.name))) from public.gift_contributions c where c.gift_id=g.id),
    (select r.name from public.reservations r where r.gift_id=g.id limit 1)
  from public.gift_catalog g order by g.sort_order,g.id;
end;
$$;

grant execute on function public.admin_list_gift_catalog() to anon;

create or replace function public.admin_save_gift(
  p_id text,p_sort_order integer,p_cat text,p_title text,p_price text,p_description text,
  p_target_amount numeric,p_allow_contributions boolean,p_allow_reservation boolean,
  p_image text default null,p_official_label text default null,p_official_url text default null,p_funding_note text default null
)
returns text language plpgsql security definer set search_path=public
as $$
begin
  perform public.assert_admin_header();
  if char_length(trim(coalesce(p_id,'')))<1 or char_length(trim(p_id))>80 then raise exception 'Identifiant invalide.'; end if;
  if char_length(trim(coalesce(p_title,'')))<1 or char_length(trim(p_title))>160 then raise exception 'Nom du cadeau invalide.'; end if;
  if p_target_amount is null or p_target_amount<0 then raise exception 'Objectif invalide.'; end if;
  insert into public.gift_catalog
  (id,sort_order,cat,title,price,description,target_amount,allow_contributions,allow_reservation,image,official_label,official_url,funding_note,updated_at)
  values(trim(p_id),coalesce(p_sort_order,0),trim(coalesce(p_cat,'')),trim(p_title),trim(coalesce(p_price,'')),
    trim(coalesce(p_description,'')),p_target_amount,coalesce(p_allow_contributions,false),coalesce(p_allow_reservation,true),
    nullif(trim(p_image),''),nullif(trim(p_official_label),''),nullif(trim(p_official_url),''),nullif(trim(p_funding_note),''),now())
  on conflict(id) do update set
    sort_order=excluded.sort_order,cat=excluded.cat,title=excluded.title,price=excluded.price,description=excluded.description,
    target_amount=excluded.target_amount,allow_contributions=excluded.allow_contributions,allow_reservation=excluded.allow_reservation,
    image=excluded.image,official_label=excluded.official_label,official_url=excluded.official_url,funding_note=excluded.funding_note,updated_at=now();
  return trim(p_id);
end;
$$;

grant execute on function public.admin_save_gift(text,integer,text,text,text,text,numeric,boolean,boolean,text,text,text,text) to anon;

create or replace function public.admin_delete_gift(p_id text)
returns boolean language plpgsql security definer set search_path=public
as $$
declare n integer;
begin
  perform public.assert_admin_header();
  delete from public.gift_contributions where gift_id=p_id;
  delete from public.reservations where gift_id=p_id;
  delete from public.gift_catalog where id=p_id;
  get diagnostics n=row_count;
  return n>0;
end;
$$;

grant execute on function public.admin_delete_gift(text) to anon;

create or replace function public.list_private_gift_contributions(
  p_code text,
  p_gift_id text
)
returns table(
  id bigint,
  amount numeric,
  message text,
  created_at timestamptz
)
language plpgsql
security definer
set search_path = public
as $privategiftlist$
declare
  v_name text;
begin
  select label
  into v_name
  from public.list_access_codes
  where active = true
    and code = trim(coalesce(p_code, ''))
  limit 1;

  if v_name is null then
    raise exception 'Accès refusé.' using errcode = '42501';
  end if;

  return query
  select
    c.id,
    c.amount,
    c.message,
    c.created_at
  from public.gift_contributions c
  where c.gift_id = p_gift_id
    and lower(trim(c.name)) = lower(trim(v_name))
  order by c.created_at desc, c.id desc;
end;
$privategiftlist$;

grant execute on function public.list_private_gift_contributions(text,text) to anon;


create or replace function public.delete_one_private_gift_contribution(
  p_code text,
  p_contribution_id bigint
)
returns boolean
language plpgsql
security definer
set search_path = public
as $privategiftdeleteone$
declare
  v_name text;
  v_deleted integer;
begin
  select label
  into v_name
  from public.list_access_codes
  where active = true
    and code = trim(coalesce(p_code, ''))
  limit 1;

  if v_name is null then
    raise exception 'Accès refusé.' using errcode = '42501';
  end if;

  delete from public.gift_contributions
  where id = p_contribution_id
    and lower(trim(name)) = lower(trim(v_name));

  get diagnostics v_deleted = row_count;
  return v_deleted > 0;
end;
$privategiftdeleteone$;

