update public.birthday_config
set settings = settings || jsonb_build_object('birth_time',''),
    updated_at = now()
where id=1
  and not (settings ? 'birth_time');

create table if not exists public.birthday_interactions (
  id bigint generated by default as identity primary key,
  interaction_type text not null check (
    interaction_type in ('quiz_result','poll_vote','challenge_done','wall_message','gallery_submission')
  ),
  visitor_name text,
  payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

alter table public.birthday_interactions enable row level security;
revoke all on public.birthday_interactions from anon, authenticated;

drop function if exists public.get_birthday_config();

create or replace function public.get_birthday_config()
returns jsonb
language plpgsql
security definer
set search_path=public
as $adminbirthdayconfig$
begin
  perform public.assert_admin_header();
  return (
    select coalesce(settings,'{}'::jsonb)
    from public.birthday_config
    where id=1
  );
end;
$adminbirthdayconfig$;

grant execute on function public.get_birthday_config() to anon;

create or replace function public.get_birthday_public_config()
returns jsonb
language sql
security definer
set search_path=public
as $birthdaypublicconfig$
  select
    jsonb_strip_nulls(coalesce(bc.settings,'{}'::jsonb) - 'murder_party' - 'schedule')
    ||
    jsonb_build_object(
      'schedule',
        case
          when coalesce((bc.settings->>'schedule_visible')::boolean,false)
          then coalesce(bc.settings->'schedule','[]'::jsonb)
          else '[]'::jsonb
        end,
      'murder_party',
        case
          when coalesce((bc.settings->'murder_party'->>'enabled')::boolean,false)
          then jsonb_build_object(
            'enabled',true,
            'title',bc.settings->'murder_party'->>'title',
            'date',bc.settings->'murder_party'->>'date',
            'location',bc.settings->'murder_party'->>'location',
            'key_moment',bc.settings->'murder_party'->>'key_moment',
            'invitation',bc.settings->'murder_party'->'invitation',
            'story_public',bc.settings->'murder_party'->'story_public',
            'zones',coalesce(bc.settings->'murder_party'->'zones','[]'::jsonb),
            'objects',coalesce(bc.settings->'murder_party'->'objects','[]'::jsonb),
            'decorations',coalesce(bc.settings->'murder_party'->'decorations','[]'::jsonb)
          )
          else jsonb_build_object('enabled',false)
        end
    )
  from public.birthday_config as bc
  where bc.id=1;
$birthdaypublicconfig$;

grant execute on function public.get_birthday_public_config() to anon;

create or replace function public.admin_save_birthday_config(p_settings jsonb)
returns boolean
language plpgsql
security definer
set search_path=public
as $adminbirthday$
begin
  perform public.assert_admin_header();
  if p_settings is null or jsonb_typeof(p_settings) <> 'object' then
    raise exception 'Configuration anniversaire invalide.';
  end if;
  update public.birthday_config
  set settings=p_settings, updated_at=now()
  where id=1;
  return found;
end;
$adminbirthday$;

grant execute on function public.admin_save_birthday_config(jsonb) to anon;

create or replace function public.submit_birthday_interaction(
  p_code text,
  p_type text,
  p_payload jsonb
)
returns bigint
language plpgsql
security definer
set search_path=public
as $birthdayinteraction$
declare
  v_id bigint;
  v_name text;
begin
  select label into v_name
  from public.list_access_codes
  where active=true and code=trim(coalesce(p_code,''))
  limit 1;

  if v_name is null then
    raise exception 'Accès refusé.' using errcode='42501';
  end if;

  if p_type not in ('quiz_result','poll_vote','challenge_done','wall_message','gallery_submission') then
    raise exception 'Type d’interaction invalide.';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Données invalides.';
  end if;

  insert into public.birthday_interactions(interaction_type,visitor_name,payload)
  values(p_type,trim(v_name),p_payload)
  returning id into v_id;

  return v_id;
end;
$birthdayinteraction$;

grant execute on function public.submit_birthday_interaction(text,text,jsonb) to anon;

create or replace function public.get_birthday_interactions(
  p_code text,
  p_type text
)
returns table(
  visitor_name text,
  payload jsonb,
  created_at timestamptz
)
language plpgsql
security definer
set search_path=public
as $birthdaypublic$
begin
  if not exists(
    select 1 from public.list_access_codes
    where active=true and code=trim(coalesce(p_code,''))
  ) then
    raise exception 'Accès refusé.' using errcode='42501';
  end if;

  return query
  select visitor_name,payload,created_at
  from public.birthday_interactions
  where interaction_type=trim(p_type)
  order by created_at desc
  limit 500;
end;
$birthdaypublic$;

grant execute on function public.get_birthday_interactions(text,text) to anon;

create or replace function public.admin_list_birthday_interactions()
returns table(
  id bigint,
  interaction_type text,
  visitor_name text,
  payload jsonb,
  created_at timestamptz
)
language plpgsql
security definer
set search_path=public
as $adminbirthdayinteractions$
begin
  perform public.assert_admin_header();
  return query
  select i.id,i.interaction_type,i.visitor_name,i.payload,i.created_at
  from public.birthday_interactions i
  order by i.created_at desc
  limit 500;
end;
$adminbirthdayinteractions$;

grant execute on function public.admin_list_birthday_interactions() to anon;


