create or replace function public.get_site_settings()
returns jsonb
language plpgsql
security definer
set search_path=public
as $siteadmin$
declare
  v_settings jsonb;
begin
  perform public.assert_admin_header();

  select settings into v_settings
  from public.site_settings
  where id=1
  for update;

  return coalesce(v_settings,'{}'::jsonb);
end;
