-- ============================================================
-- HYDRA : DEFINITIONS FINALES
-- Référence finale : exécuter tout ce fichier dans Supabase.
-- Cette section réaffirme la table et les RPC Hydra utilisés par admin.html.

create table if not exists public.hydra_access_assignments (
  id bigint generated by default as identity primary key,
  access_id bigint not null references public.list_access_codes(id) on delete cascade,
  hydra_player_name text not null,
  private_token text not null unique,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  unique(access_id, hydra_player_name)
);

create index if not exists hydra_access_assignments_access_idx
  on public.hydra_access_assignments(access_id);

alter table public.hydra_access_assignments enable row level security;
revoke all on public.hydra_access_assignments from anon, authenticated;

create or replace function public.admin_list_hydra_access_assignments()
returns table(
  assignment_id bigint,
  access_id bigint,
  person_name text,
  hydra_player_name text,
  private_token text,
  active_assignment boolean
)
language plpgsql
security definer
set search_path=public
as $$
begin
  perform public.assert_admin_header();
  return query
  select
    haa.id,
    haa.access_id,
    lac.label,
    haa.hydra_player_name,
    haa.private_token,
    haa.active
  from public.hydra_access_assignments haa
  join public.list_access_codes lac on lac.id=haa.access_id
  order by lac.created_at desc, haa.created_at asc;
end;
$$;

grant execute on function public.admin_list_hydra_access_assignments() to anon;

drop function if exists public.admin_sync_hydra_access_assignments(bigint,jsonb);
create or replace function public.admin_sync_hydra_access_assignments(
  p_access_id bigint,
  p_players jsonb default '[]'::jsonb
)
returns table(
  assignment_id bigint,
  access_id bigint,
  person_name text,
  hydra_player_name text,
  private_token text,
  active_assignment boolean
)
language plpgsql
security definer
set search_path=public
as $$
declare
  v_name text;
  v_private_token text;
begin
  perform public.assert_admin_header();

  if not exists(
    select 1 from public.list_access_codes where id=p_access_id
  ) then
    raise exception 'Accès introuvable.';
  end if;

  if p_players is null or jsonb_typeof(p_players) <> 'array' then
    raise exception 'La sélection Hydra est invalide.';
  end if;

  -- Vérifie que chaque nom sélectionné existe dans la configuration Hydra.
  for v_name in
    select distinct trim(value)
    from jsonb_array_elements_text(p_players) as value
    where trim(value) <> ''
  loop
    if not exists(
      select 1
      from jsonb_array_elements(
        coalesce(
          (select settings->'murder_party'->'players'
           from public.birthday_config
           where id=1),
          '[]'::jsonb
        )
      ) as p
      where lower(trim(p->>'name'))=lower(v_name)
    ) then
      raise exception 'Joueur Hydra introuvable : %.', v_name;
    end if;
  end loop;

  -- Supprime les dossiers retirés de la sélection.
  delete from public.hydra_access_assignments haa
  where haa.access_id=p_access_id
    and not exists(
      select 1
      from jsonb_array_elements_text(p_players) as value
      where lower(trim(value))=lower(trim(haa.hydra_player_name))
    );

  -- Ajoute les nouveaux dossiers ou réactive les dossiers existants.
  for v_name in
    select distinct trim(value)
    from jsonb_array_elements_text(p_players) as value
    where trim(value) <> ''
  loop
    if exists(
      select 1
      from public.hydra_access_assignments haa
      where haa.access_id=p_access_id
        and lower(trim(haa.hydra_player_name))=lower(v_name)
    ) then
      update public.hydra_access_assignments haa
      set active=true
      where haa.access_id=p_access_id
        and lower(trim(haa.hydra_player_name))=lower(v_name);
    else
      loop
        v_private_token :=
          'HYDRA-' || upper(substr(
            md5(random()::text || clock_timestamp()::text || p_access_id::text || v_name),
            1,
            24
          ));
        exit when not exists(
          select 1
          from public.hydra_access_assignments haa
          where haa.private_token=v_private_token
        );
      end loop;

      insert into public.hydra_access_assignments(
        access_id, hydra_player_name, private_token, active
      )
      values(
        p_access_id, v_name, v_private_token, true
      );
    end if;
  end loop;

  return query
  select
    haa.id,
    haa.access_id,
    lac.label,
    haa.hydra_player_name,
    haa.private_token,
    haa.active
  from public.hydra_access_assignments haa
  join public.list_access_codes lac on lac.id=haa.access_id
  where haa.access_id=p_access_id
  order by haa.created_at asc;
end;
$$;

grant execute on function public.admin_sync_hydra_access_assignments(bigint,jsonb) to anon;

notify pgrst,'reload schema';



-- ============================================================
-- HYDRA : UN SEUL LIEN PAR PERSONNE / PLUSIEURS FICHES
-- Le code d'accès de la personne suffit désormais pour afficher
-- tous les dossiers Hydra qui lui sont attribués.
-- Les anciens jetons privés restent conservés en base pour compatibilité,
-- mais ils ne sont plus nécessaires pour l'affichage des fiches.

drop function if exists public.get_my_hydra_dossiers(text);
create or replace function public.get_my_hydra_dossiers(
  p_code text
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $hydramulti$
declare
  v_access_id bigint;
  v_legacy_name text;
  v_players jsonb;
  v_result jsonb := '[]'::jsonb;
  v_name text;
  v_player jsonb;
begin
  select id, hydra_player_name
  into v_access_id, v_legacy_name
  from public.list_access_codes
  where active=true
    and code=trim(coalesce(p_code,''))
  limit 1;

  if v_access_id is null then
    raise exception 'Accès refusé.' using errcode='42501';
  end if;

  select settings->'murder_party'->'players'
  into v_players
  from public.birthday_config
  where id=1;

  -- Nouveau système : plusieurs dossiers pour le même code.
  for v_name in
    select haa.hydra_player_name
    from public.hydra_access_assignments haa
    where haa.access_id=v_access_id
      and haa.active=true
    order by haa.created_at asc
  loop
    select value
    into v_player
    from jsonb_array_elements(coalesce(v_players,'[]'::jsonb))
    where lower(trim(value->>'name'))=lower(trim(v_name))
    limit 1;

    if v_player is not null then
      v_result := v_result || jsonb_build_array(v_player);
    end if;
  end loop;

  -- Compatibilité avec l'ancien champ unique list_access_codes.hydra_player_name.
  if jsonb_array_length(v_result)=0
     and coalesce(trim(v_legacy_name),'') <> '' then
    select value
    into v_player
    from jsonb_array_elements(coalesce(v_players,'[]'::jsonb))
    where lower(trim(value->>'name'))=lower(trim(v_legacy_name))
    limit 1;

    if v_player is not null then
      v_result := jsonb_build_array(v_player);
    end if;
  end if;

  return v_result;
end;
$hydramulti$;

grant execute on function public.get_my_hydra_dossiers(text) to anon;

-- Compatibilité : l'ancienne RPC renvoie désormais la première fiche.
drop function if exists public.get_my_hydra_dossier(text,text);
create or replace function public.get_my_hydra_dossier(
  p_code text,
  p_hydra_token text default null
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $hydrasingle$
declare
  v_all jsonb;
begin
  v_all := public.get_my_hydra_dossiers(p_code);

  if jsonb_typeof(v_all)='array' and jsonb_array_length(v_all)>0 then
    return v_all->0;
  end if;

  return '{}'::jsonb;
end;
$hydrasingle$;

grant execute on function public.get_my_hydra_dossier(text,text) to anon;

notify pgrst,'reload schema';


