          when 'Mario' then value || jsonb_build_object('tenue_parfaite', 'Sweat à capuche vert forêt sous une veste sans manches bleu marine, jean noir, chaussures de randonnée et sifflet de dressage au cou.')
          when 'Tony' then value || jsonb_build_object('tenue_parfaite', 'Surchemise bleu moyen, t-shirt blanc, pantalon cargo noir, baskets gris clair, petite sacoche tech et badge OSINT.')
          when 'Lino' then value || jsonb_build_object('tenue_parfaite', 'Surchemise marron chocolat, t-shirt gris charbon, pantalon noir, bottes marron foncé, sacoche en toile et trousse à objets Hydra.')
          when 'Emy' then value || jsonb_build_object('tenue_parfaite', 'Blazer prune, chemise blanche, pantalon noir droit, mocassins noirs, petite montre et porte-documents fin.')
          when 'Milo' then value || jsonb_build_object('tenue_parfaite', 'Harnais bleu nuit avec écusson Hydra, bandana rouge sombre, médaille d’identification et petite cape légère imperméable pour les déplacements.')
          else value
      end
      order by ord
    )
    from jsonb_array_elements(
      coalesce(bc.settings->'murder_party'->'players','[]'::jsonb)
    ) with ordinality as t(value,ord)
  ),
  true
),
updated_at=now()
where bc.id=1;

notify pgrst,'reload schema';


