ran","Fond d’écran Hydra fictif","Clavier","Cartes FRAGMENT IA","LED bleue"],"setup":"Afficher une interface purement décorative sans connexion à un système réel.","purpose":"Donner un lieu visuel à l’IA."},{"id":10,"name":"Badges des agents","zone":"Tous les joueurs","priority":"Essentiel","materials":["Cartons imprimés","Tours de cou ou pinces","Numéros de joueur"],"setup":"Associer chaque joueur à son personnage et à son niveau d’accès.","purpose":"Faciliter les interactions."},{"id":11,"name":"Enveloppes de preuves","zone":"Toutes les zones","priority":"Essentiel","materials":["Enveloppes kraft/noires","Stickers 01–55","Tampon CONFIDENTIEL"],"setup":"Classer les énigmes et documents par numéro.","purpose":"Contrôler la progression."},{"id":12,"name":"Table du dernier acte","zone":"Lieu central","priority":"Essentiel","materials":["Grande enveloppe rouge/bordeaux","Horloge visible","Dossier « 21h10 »","Carte de vote final"],"setup":"Ne sortir cette table qu’au moment voulu.","purpose":"Créer un vrai changement d’acte."}],"decoration_shopping":["Tissu noir ou bleu nuit","Ruban rouge/bordeaux","Papier/carton pour affiches et dossiers","Post-it + ficelle/ruban pour le tableau de preuves","LED ambre, violette/rouge et bleue","Enveloppes kraft/noires","Faux bijoux ou accessoires déjà disponibles","Vieux livre ou livre de décor","Ordinateur/écran pour l’ambiance IA","Accessoires de laboratoire inoffensifs et propres","Étiquettes « ACCESSOIRE — FICTION »","Badges imprimés pour les 19 personnages"]}$hydra_full$::jsonb,
